-- 546: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 8 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_546_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_546_guard;
INSERT INTO _migration_546_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_036' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Write down the value of cos 60°.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. √3/2","B. 1","C. 0","D. 0.5"]' AND q.correct_answer IS 'D' AND q.explanation IS 'cos 60° is a standard exact value: 0.5 (that is, 1/2). (√3/2 is cos 30°, confusing the complementary special angles.) Therefore the correct answer is D: 0.5.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write down' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_036' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_546_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_037' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a right-angled triangle, the side opposite angle θ is 6 cm and the side adjacent to θ is 8 cm. Find tan θ.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3/4","B. 4/3","C. 3/5","D. 4/5"]' AND q.correct_answer IS 'A' AND q.explanation IS 'tan θ = opposite ÷ adjacent = 6/8 = 3/4. (3/5 is sin θ: the hypotenuse is √(6² + 8²) = 10 cm, so sin θ = 6/10 = 3/5 — the wrong ratio.) Therefore the correct answer is A: 3/4.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_037' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_546_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_038' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A right-angled triangle has a hypotenuse of 10 cm and an angle of 30°. Find the length of the side opposite the 30° angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 8.7 cm","B. 5 cm","C. 5√3 cm","D. 10 cm"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The opposite side equals hypotenuse × sin 30° = 10 × 0.5 = 5 cm. (5√3 cm ≈ 8.7 cm is the adjacent side, 10 cos 30°, not the side asked for.) Therefore the correct answer is B: 5 cm.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_038' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_546_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_039' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A boy stands 20 m from the foot of a vertical mast. The angle of elevation of the top of the mast from the boy is 45°. Calculate the height of the mast.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 20√2 m","B. 10 m","C. 20 m","D. 40 m"]' AND q.correct_answer IS 'C' AND q.explanation IS 'tan 45° = height ÷ distance = height ÷ 20. Since tan 45° = 1, the height is 20 × 1 = 20 m. (20√2 m ≈ 28.3 m is the line-of-sight distance from the boy to the top, not the height.) Therefore the correct answer is C: 20 m.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_039' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_546_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_040' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A right-angled triangle has a hypotenuse of 8 cm and an angle of 60°. Find the length of the side adjacent to the 60° angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 4√3 cm","B. 8 cm","C. 16 cm","D. 4 cm"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The adjacent side equals hypotenuse × cos 60° = 8 × 0.5 = 4 cm. (4√3 cm ≈ 6.9 cm is the side opposite the 60° angle, 8 sin 60°.) Therefore the correct answer is D: 4 cm.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_040' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
